Sure, I'd be happy to help you with that! Here's a Python program that meets your requirements. This program uses a dictionary to store the contacts, which makes it easy to add, remove, and search for contacts. The while loop ensures that the user continues to interact with the program until they choose to exit.

```python
phonebook = {}

def add_contact():
    """Add a new contact to the phonebook."""
    name = input("Enter the name of the contact: ")
    number = input("Enter the phone number (e.g., 123-45-6789): ")
    phonebook[name] = number
    print(f"{name}: {number}")

def remove_contact():
    """Remove a contact from the phonebook."""
    name = input("Enter the name of the contact to remove: ")
    if name in phonebook:
        del phonebook[name]
        print(f"Contact {name} removed from the phonebook.")
    else:
        print(f"Contact {name} not found in the phonebook.")

def search_contact():
    """Search for a contact in the phonebook."""
    name = input("Enter the name of the contact to search for: ")
    if name in phonebook:
        print(f"{name}: {phonebook[name]}")
    else:
        print(f"Contact {name} not found in the phonebook.")

def main():
    """The main function to manage the phonebook."""
    while True:
        print("\nPhonebook Management System")
        print("1. Add a contact")
        print("2. Remove a contact")
        print("3. Search for a contact")
        print("4. Exit")

        choice = input("Enter the number of the action you want to perform: ")

        if choice == "1":
            add_contact()
        elif choice == "2":
            remove_contact()
        elif choice == "3":
            search_contact()
        elif choice == "4":
            print("Exiting the phonebook management system...")
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```

This program will keep prompting the user for input until they choose to exit. You can customize the prompts and error messages as needed.
